import {createClient} from 'https://esm.sh/@supabase/supabase-js@2';
const C=window.STK_CONFIG||{};const configured=/^https:\/\//.test(C.supabaseUrl)&&!C.supabaseUrl.includes('PASTE_')&&!C.supabaseAnonKey.includes('PASTE_');
const db=configured?createClient(C.supabaseUrl,C.supabaseAnonKey):null;
const state={user:null,profile:null,page:'dashboard',services:[],committees:[],tasks:[],displays:[],users:[],publications:[],serviceFilter:'',editId:null,loading:false};
const $=s=>document.querySelector(s);const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const opt=(v,t)=>`<option value="${escape(v)}">${escape(t)}</option>`;
const isAdmin=()=>state.profile?.role==='super_admin';const leader=()=>['super_admin','department_saint'].includes(state.profile?.role);const canManage=t=>isAdmin()||(state.profile?.role==='department_saint'&&state.profile.department===t.department);const canWrite=s=>isAdmin()||(state.profile?.department===s.department&&(state.profile.role==='department_saint'||state.profile.committee_id===s.committee_id));const say=(msg,error=false)=>{const el=document.createElement('div');el.className='toast';el.textContent=msg;if(error)el.style.background='#992e38';document.body.appendChild(el);setTimeout(()=>el.remove(),5000)};
const label={draft:'ડ્રાફ્ટ',submitted:'મંજૂરી માટે',approved:'મંજૂર',rejected:'સુધારા માટે પરત',in_progress:'કાર્ય ચાલુ',completed:'પૂર્ણ (ચકાસણી બાકી)',verified:'ચકાસાયેલું'};
const nav=[['dashboard','◫','ડેશબોર્ડ'],['services','▤','સમિતિઓ અને સેવાઓ'],['tasks','☷','ઓનલાઇન કામગીરી'],['new','＋','નવી કામગીરી'],['displays','▣','ટીવી ડિસ્પ્લે'],['users','♙','યુઝર અને અધિકાર'],['calendar','▦','માસિક કેલેન્ડર'],['approvals','✓','મંજૂરી ઇનબૉક્સ'],['reports','▥','રિપોર્ટ અને નિકાસ'],['import','⇧','જૂના ડેટા ઇમ્પોર્ટ']];
function panel(title,inner){return `<section class="panel"><h2>${title}</h2>${inner}</section>`}function notice(s,err=false){return `<div class="notice ${err?'error':''}">${s}</div>`}
async function req(p){const {data,error}=await p;if(error)throw Error(error.message);return data}
async function setup(){
 if(!configured){$('#app').innerHTML=`<main class="center">${notice('config.js માં Supabase URL અને public key ચકાસો.',true)}</main>`;return}
 // Show useful UI immediately. The session call can be slow on a cold network.
 $('#app').innerHTML='<div class="boot-skeleton"><img src="stk-logo.svg" width="70" alt="STK"><h2>STK Karyalaya</h2><p data-i18n="Loading portal…">પોર્ટલ શરૂ થઈ રહ્યું છે…</p><div class="boot-progress"></div></div>';
 const timeout=new Promise((_,reject)=>setTimeout(()=>reject(Error('સર્વરનો જવાબ મોડો છે. ઇન્ટરનેટ ચકાસીને ફરી પ્રયાસ કરો.')),16000));
 try{const {data:{session}}=await Promise.race([db.auth.getSession(),timeout]);state.user=session?.user||null;if(state.user)await loadApp();else renderLogin()}catch(err){$('#app').innerHTML=`<main class="center">${notice(escape(err.message),true)}<button class="button" id="retry-start">ફરી પ્રયાસ કરો</button></main>`;$('#retry-start').onclick=setup}
 db.auth.onAuthStateChange((event,session)=>{if(event==='SIGNED_OUT'){state.user=null;state.profile=null;renderLogin()}else if(event==='SIGNED_IN'&&session?.user&&!state.profile&&!state.loading){state.user=session.user;void loadApp()}})
}
const loginEmail=username=>`${username.trim().toLowerCase()}@stk-users.example.com`;
const goodUsername=s=>/^[a-z][a-z0-9_]{2,31}$/.test(s);
async function accountApi(payload,authenticated=false){const headers={'Content-Type':'application/json','apikey':C.supabaseAnonKey};if(authenticated){const {data:{session}}=await db.auth.getSession();if(!session)throw Error('ફરી લૉગિન કરો');headers.Authorization=`Bearer ${session.access_token}`}const r=await fetch(`${C.supabaseUrl}/functions/v1/stk-accounts`,{method:'POST',headers,body:JSON.stringify(payload)});const v=await r.json().catch(()=>({}));if(!r.ok)throw Error(v.error||`સર્વર ભૂલ (${r.status})`);return v}
function renderLogin(){state.profile=null;$('#app').innerHTML=`<div class="login"><div class="login-card"><div class="stk-preferences" data-stk-prefs></div><div class="login-brand"><img src="stk-logo.svg" alt="STK logo" class="brand-logo"/><h1>STK Karyalaya</h1></div><p class="muted">EDU • HRM • ADM | Username Login</p><form id="login"><div class="field"><label>યુઝરનેમ</label><input required type="text" name="username" pattern="[a-zA-Z][a-zA-Z0-9_]{2,31}" autocomplete="username" placeholder="superadmin"></div><div class="field"><label>પાસવર્ડ</label><input required type="password" name="password" autocomplete="current-password"></div><button class="button" type="submit">લૉગિન કરો</button></form><p class="small"><a href="#" id="forgot">પાસવર્ડ ભૂલી ગયા? (Forgot Password)</a></p><p class="small muted">નવા યુઝરનું એકાઉન્ટ Super Admin બનાવે છે. ઈમેલની જરૂર નથી.</p></div></div>`;$('#login').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),username=String(f.get('username')).toLowerCase(),password=String(f.get('password'));if(!goodUsername(username))return say('માન્ય યુઝરનેમ દાખલ કરો',true);try{await req(db.auth.signInWithPassword({email:loginEmail(username),password}))}catch(ex){say('યુઝરનેમ અથવા પાસવર્ડ ખોટો છે.',true)}};$('#forgot').onclick=e=>{e.preventDefault();renderForgot()}}
function renderForgot(){state.profile=null;$('#app').innerHTML=`<div class="login"><div class="login-card"><div class="stk-preferences" data-stk-prefs></div><h2>પાસવર્ડ ફરી સેટ કરો</h2><p class="muted small">તમને આપેલો ગુપ્ત Recovery Code દાખલ કરો. કોડ નથી તો Super Admin પાસેથી નવો પાસવર્ડ મેળવો.</p><form id="recover"><div class="field"><label>યુઝરનેમ</label><input name="username" required autocomplete="username" placeholder="superadmin"></div><div class="field"><label>Recovery Code</label><input name="recovery" required autocomplete="off"></div><div class="field"><label>નવો પાસવર્ડ (ઓછામાં ઓછા 3 અક્ષર)</label><input name="password" required minlength="3" type="password" autocomplete="new-password"></div><button class="button">પાસવર્ડ બદલો</button></form><p class="small"><a href="#" id="back-login">લૉગિન પર પાછા જાઓ</a></p></div></div>`;$('#back-login').onclick=e=>{e.preventDefault();renderLogin()};$('#recover').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);try{const r=await accountApi({action:'recover',username:String(f.get('username')).trim().toLowerCase(),recovery_code:String(f.get('recovery')).trim(),password:String(f.get('password'))});alert('પાસવર્ડ બદલાઈ ગયો છે. નવો Recovery Code સુરક્ષિત જગ્યાએ સાચવો (પછી ફરી દેખાશે નહીં): '+r.recovery_code);renderLogin()}catch(ex){say(ex.message,true)}}}
async function loadApp(){if(state.loading)return;state.loading=true;
 $('#app').innerHTML='<div class="boot-skeleton"><img src="stk-logo.svg" width="70" alt="STK"><h2>STK Karyalaya</h2><p>સ્વાગત છે! માહિતી લોડ થઈ રહી છે…</p><div class="boot-progress"></div></div>';
 try{state.profile=await req(db.from('profiles').select('*').eq('id',state.user.id).single());
 if(state.profile.role==='pending'){$('#app').innerHTML=`<div class="login"><div class="login-card"><div class="stk-preferences" data-stk-prefs></div><h2>અધિકાર મંજૂરી બાકી</h2>${notice('Super Admin વિભાગ અને સમિતિ સોંપશે ત્યારબાદ પોર્ટલ ખુલશે.')}<button class="button" id="refresh">ફરી ચકાસો</button><button class="button light" id="out">લૉગઆઉટ</button></div></div>`;$('#refresh').onclick=()=>{state.loading=false;loadApp()};$('#out').onclick=()=>db.auth.signOut();return}
 const seed=await fetch('seed.json').then(r=>{if(!r.ok)throw Error('seed.json ઉપલબ્ધ નથી');return r.json()});state.committees=seed.committees;
 // Start independent reads together; show shell as soon as services are available.
 const serviceRequest=req(db.from('services').select('*').order('id'));
 const background=reload();
 state.services=await serviceRequest;
 state.loading=false;render();
 await background;render();
 }catch(ex){say(ex.message,true);$('#app').innerHTML=`<main class="center"><h2>પોર્ટલ લોડ ન થયું</h2><p>${escape(ex.message)}</p><button class="button" id="retry-app">ફરી પ્રયાસ કરો</button></main>`;$('#retry-app').onclick=loadApp}finally{state.loading=false}}
async function reload(){const queries=[db.from('work_items').select('*').order('created_at',{ascending:false}).limit(500),db.from('displays').select('*').order('name'),db.from('publications').select('*').order('created_at',{ascending:false})];if(isAdmin())queries.push(db.from('profiles').select('*').order('created_at',{ascending:false}));const results=await Promise.allSettled(queries.map(req));const names=['tasks','displays','publications','users'];for(let i=0;i<results.length;i++){if(results[i].status==='fulfilled')state[names[i]]=results[i].value;else{console.warn('Could not load '+names[i],results[i].reason);state[names[i]]=[]}}}

function render(){
 const role=state.profile?.role||'';const dept=state.profile?.department||'';
 const simple=role==='samiti_sanchalak';
 const menu=simple?[['dashboard','⌂','મારું હોમ'],['new','＋','નવી નોંધ બનાવો'],['tasks','☷','મારી કામગીરી'],['calendar','▦','આયોજન'],['import','⇧','ફાઇલ અપલોડ']]:role==='department_saint'?[['dashboard','⌂','હોમ'],['tasks','☷','વિભાગની કામગીરી'],['new','＋','નવી નોંધ'],['calendar','▦','આયોજન'],['approvals','✓','મંજૂરી'],['displays','▣','ટીવી ડિસ્પ્લે'],['import','⇧','ફાઇલ અપલોડ'],['reports','▥','રિપોર્ટ'],['services','▤','સેવાઓ']]:[['dashboard','⌂','હોમ'],['tasks','☷','તમામ કામગીરી'],['new','＋','નવી નોંધ'],['approvals','✓','મંજૂરી'],['calendar','▦','આયોજન'],['import','⇧','ફાઇલ અપલોડ'],['displays','▣','ટીવી'],['users','♙','યુઝર'],['reports','▥','રિપોર્ટ'],['services','▤','સેવાઓ']];
 const titles={dashboard:'મારું કાર્યાલય',services:'સમિતિઓ અને સેવાઓ',tasks:'મારી કામગીરી',new:'નવી નોંધ બનાવો',displays:'ટીવી ડિસ્પ્લે',users:'યુઝર મેનેજમેન્ટ',detail:'કાર્યની વિગત',calendar:'માસિક આયોજન',approvals:'મંજૂરી માટેના કામ',reports:'રિપોર્ટ',import:'જૂની ફાઇલ અપલોડ કરો'};
 $('#app').innerHTML=`<div class="shell easy-shell"><aside class="side easy-side"><div class="brand brand-lockup"><img src="stk-logo.svg" alt="STK Karyalaya logo" class="brand-logo"/><span>STK Karyalaya<small>સેવા • સંકલન • સરળતા</small></span></div><div class="easy-side-caption">તમારા કામના વિકલ્પો</div><nav class="nav">${menu.map(([id,icon,name])=>`<button class="nav-btn ${state.page===id?'active':''}" data-page="${id}"><span class="easy-nav-icon">${icon}</span> ${name}</button>`).join('')}</nav><div class="easy-user"><span class="easy-avatar">${escape((state.profile.full_name||state.profile.username||'S').slice(0,1))}</span><div><b>${escape(state.profile.full_name||state.profile.username)}</b><small>${escape(dept||'STK')} ${simple?'• સમિતિ સંચાલક':role==='department_saint'?'• વિભાગીય સંત':'• Super Admin'}</small></div></div><button class="logout" id="logout">બહાર નીકળો</button></aside><main class="main"><div class="top easy-top"><div><div class="easy-breadcrumb">STK Karyalaya ${dept?' / '+escape(dept):''}</div><h1>${titles[state.page]||'STK Karyalaya'}</h1></div><div class="header-actions"><div class="stk-preferences" data-stk-prefs></div><button class="button light easy-refresh" id="reload" title="માહિતી અપડેટ">↻</button></div></div><div id="content"></div></main></div>`;
 document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>go(b.dataset.page));$('#logout').onclick=()=>db.auth.signOut();$('#reload').onclick=async()=>{try{await reload();render();say('માહિતી અપડેટ થઈ')}catch(e){say(e.message,true)}};view();
}
function go(page){state.page=page;state.editId=null;render()}function serviceById(id){return state.services.find(s=>s.id===id)}function view(){const fn={dashboard:dashboard,services:servicesView,tasks:tasksView,new:newView,displays:displaysView,users:usersView,detail:detailView,calendar:calendarView,approvals:approvalsView,reports:reportsView,import:importView}[state.page]||dashboard;$('#content').innerHTML=fn();wire()}
function dashboard(){
 const dept=state.profile?.department,role=state.profile?.role;
 const mine=role==='samiti_sanchalak'?state.tasks.filter(t=>t.committee_id===state.profile.committee_id):state.tasks;
 const ownServices=state.services.filter(canWrite);const awaiting=mine.filter(t=>t.state==='submitted');const draft=mine.filter(t=>['draft','rejected'].includes(t.state));
 const upcoming=mine.filter(t=>t.planned_for).sort((a,b)=>(a.planned_for||'').localeCompare(b.planned_for||'')).slice(0,5);
 const myCommittee=state.committees.find(c=>c.id===state.profile.committee_id);
 const today=new Date().toLocaleDateString('gu-IN',{day:'numeric',month:'long',year:'numeric'});
 const cards=[['new','＋','નવી નોંધ બનાવો','કામ શરૂ કરવા અહીં ક્લિક કરો','mint'],['tasks','☷','મારી નોંધો જુઓ','પહેલાં કરેલું કામ અહીં મળશે','lavender'],['import','⇧','જૂની ફાઇલ અપલોડ','Excel, CSV, PDF અને અન્ય ફાઇલ','peach'],['calendar','▦','માસિક આયોજન','આ મહિનાનું આયોજન જુઓ','sky']];
 return `<section class="easy-hero"><div><div class="easy-hero-tag">${escape(today)}</div><h2>જય સ્વામિનારાયણ 🙏</h2><p>${escape(state.profile.full_name||state.profile.username)}, આજે આપ શું કામ કરવા ઇચ્છો છો?</p><button class="button easy-primary" data-page="new">＋ નવી કામગીરી શરૂ કરો</button></div><div class="easy-hero-symbol" aria-hidden="true">✦<span>સેવા • વ્યવસ્થા</span></div></section>
 ${role==='samiti_sanchalak'?`<div class="easy-committee-banner"><span>મારી સમિતિ</span><strong>${escape(myCommittee?.name||ownServices[0]?.committee||'સમિતિ નક્કી કરવાની બાકી')}</strong><small>${escape(dept||'')}</small></div>`:''}
 <div class="easy-stats"><div><span>મારી કુલ નોંધો</span><b>${mine.length}</b></div><div><span>ડ્રાફ્ટ / સુધારો</span><b>${draft.length}</b></div><div><span>મંજૂરી માટે</span><b>${awaiting.length}</b></div></div>
 <div class="easy-section-title"><h2>મારે શું કરવું છે?</h2><span>નીચેનો વિકલ્પ પસંદ કરો</span></div><div class="easy-action-grid">${cards.map(([id,icon,title,desc,color])=>`<button class="easy-action ${color}" data-page="${id}"><span class="easy-action-symbol">${icon}</span><b>${title}</b><small>${desc}</small><span class="easy-arrow">→</span></button>`).join('')}</div>
 ${dept==='EDU'||role==='super_admin'?eduPlanningWidget():''}
 <div class="easy-bottom-grid">${panel('તાજેતરમાં કરેલું કામ',mine.length?taskTable(mine.slice(0,5)):notice('હજુ કોઈ નોંધ બનાવી નથી. ઉપરથી “નવી નોંધ બનાવો” પસંદ કરો.'))}${panel('આગામી આયોજન',upcoming.length?`<div class="agenda">${upcoming.map(t=>`<button class="agenda-line" data-open="${t.id}"><time>${escape(t.planned_for)}</time><span><b>${escape(t.title)}</b><small>${escape(t.assigned_to||'')}</small></span><span>→</span></button>`).join('')}</div>`:notice('આગામી આયોજન ઉમેરાયેલું નથી.'))}</div>`;
}
function servicesView(){const dept=state.profile.department;const available=state.services.filter(s=>(isAdmin()||s.department===dept));const grouped=Object.groupBy?Object.groupBy(available,s=>s.committee_id):available.reduce((a,s)=>(a[s.committee_id]??=[]).push(s),{});return `<div class="toolbar"><input class="control" placeholder="સમિતિ અથવા સેવા શોધો…" id="s-search" style="flex:1"></div><div id="service-groups">${serviceGroups(grouped)}</div>`}
function serviceGroups(groups,keyword=''){return Object.entries(groups).map(([id,services])=>{const arr=services.filter(s=>(`${s.name} ${s.committee} ${s.owner}`).toLowerCase().includes(keyword));if(!arr.length)return '';return panel(`${escape(services[0].department)} • ${escape(services[0].committee)} <span class="pill">${arr.length} સેવાઓ</span>`,`<div class="tablewrap"><table><thead><tr><th>સેવા</th><th>મૂળ જવાબદાર</th><th></th></tr></thead><tbody>${arr.map(s=>`<tr><td><b>${escape(s.name)}</b><div class="muted small">${escape(s.form_hint)}</div></td><td>${escape(s.owner)}</td><td>${canWrite(s)?`<button class="button light" data-newservice="${escape(s.id)}">નવી નોંધ</button>`:''}</td></tr>`).join('')}</tbody></table></div>`)}).join('')||notice('માહિતી મળી નથી')}
function taskTable(tasks){return `<div class="tablewrap"><table><thead><tr><th>કાર્ય</th><th>સેવા</th><th>તારીખ</th><th>સ્થિતિ</th><th></th></tr></thead><tbody>${tasks.map(t=>`<tr class="clickable" data-open="${t.id}"><td><b>${escape(t.title)}</b><div class="small muted">${escape(t.department)} • ${escape(t.assigned_to)}</div></td><td>${escape(serviceById(t.service_id)?.name||t.service_id)}</td><td>${escape(t.planned_for||'—')}</td><td><span class="tag ${t.state}">${label[t.state]||t.state}</span></td><td>વિગત →</td></tr>`).join('')||'<tr><td colspan="5" class="muted">હજુ કોઈ કાર્ય નથી.</td></tr>'}</tbody></table></div>`}
function tasksView(){const tasks=state.tasks;return panel('તમામ કાર્યરેકોર્ડ',`<div class="toolbar"><input id="t-search" class="control" placeholder="કાર્ય શોધો…" style="flex:1"><select id="t-state" class="control">${opt('','બધી સ્થિતિ')}${Object.entries(label).map(([k,v])=>opt(k,v)).join('')}</select><button class="button" data-page="new">+ નવી કામગીરી</button></div><div id="filtered-tasks">${taskTable(tasks)}</div>`) }
function newView(){const allowed=state.services.filter(canWrite);if(!allowed.length)return notice('હજુ આપને સમિતિ ફાળવાઈ નથી. વિભાગીય સંત અથવા Super Adminનો સંપર્ક કરો.');const sid=state.serviceFilter&&allowed.find(s=>s.id===state.serviceFilter)?state.serviceFilter:allowed[0].id;const s=serviceById(sid);return `<section class="easy-wizard-heading"><span class="easy-step">1</span><div><h2>કઈ સેવા માટે નોંધ બનાવવી છે?</h2><p>પહેલાં સેવા પસંદ કરો, પછી માત્ર જરૂરી માહિતી ભરો.</p></div></section><form id="new-work" class="easy-form"><div class="easy-form-section"><div class="field"><label>સેવા પસંદ કરો *</label><select name="service_id" id="service-select">${allowed.map(x=>opt(x.id,`${x.committee} — ${x.name}`)).join('')}</select></div></div><div class="easy-wizard-heading"><span class="easy-step">2</span><div><h2>આ કામની સામાન્ય માહિતી</h2><p>શીર્ષક અને જરૂરિયાત મુજબ તારીખ ભરો.</p></div></div><div class="easy-form-section"><div class="form-grid"><div class="field span2"><label>શું કામ કરવાનું છે? *</label><input name="title" required placeholder="ઉદાહરણ: નવેમ્બર મહિનાનું આયોજન" /></div><div class="field"><label>તારીખ</label><input name="planned_for" type="date"></div><div class="field"><label>સ્થળ (વૈકલ્પિક)</label><input name="place" placeholder="હોલ / રૂમ"></div><div class="field span2"><label>કોને જવાબદારી આપવી છે?</label><input name="assigned_to" placeholder="સંત / સેવકનું નામ"></div><div class="field span2"><label>વધુ વિગત (વૈકલ્પિક)</label><textarea name="details" rows="3" placeholder="કામની ટૂંકી સમજણ"></textarea></div></div></div><div class="easy-wizard-heading"><span class="easy-step">3</span><div><h2>સેવા મુજબની જરૂરી વિગતો</h2><p>આ સેવાને લગતી વિગતો ભરો અને સાચવો.</p></div></div><div class="easy-form-section"><div id="dynamic-fields">${serviceFields(s)}</div><details class="easy-more"><summary>વધારાની માહિતી / લાઇનવાર આયોજન (જરૂર હોય ત્યારે)</summary><div class="field"><label>આયોજનની અન્ય નોંધો</label><textarea name="planning_lines" placeholder="તારીખ | સમય | પ્રવૃત્તિ | સ્થળ | જવાબદાર"></textarea></div><div id="service-help">${hint(s)}</div></details></div><div class="easy-form-footer"><button type="button" class="button light" data-page="dashboard">પાછા જાઓ</button><button type="submit" class="button easy-primary">✓ નોંધ સાચવો</button><small>આ નોંધ સૌપ્રથમ ડ્રાફ્ટ તરીકે સાચવાશે. પછી મંજૂરી માટે મોકલી શકશો.</small></div></form>`}
function hint(s){return notice(`<b>${escape(s.name)}</b><br>ફોર્મ સૂચન: ${escape(s.form_hint)}<br>સૂચિત પ્રક્રિયા: ${escape(s.workflow_hint)}`)}
function detailView(){const t=state.tasks.find(x=>x.id===state.editId);if(!t)return notice('કાર્ય મળ્યું નથી.',true);const s=serviceById(t.service_id);const transitions={draft:[['submitted','મંજૂરી માટે મોકલો']],rejected:[['submitted','ફરી મંજૂરી માટે મોકલો']],submitted:canManage(t)?[['approved','મંજૂર કરો'],['rejected','સુધારા માટે પરત કરો']]:[],approved:[['in_progress','કાર્ય શરૂ કરો']],in_progress:[['completed','કાર્ય પૂર્ણ કરો']],completed:canManage(t)?[['verified','અંતિમ ચકાસણી પૂર્ણ']]:[]};let actions=(transitions[t.state]||[]).map(([next,title])=>`<button class="button" data-transition="${next}">${title}</button>`).join('');if(canManage(t)&&['approved','in_progress','completed','verified'].includes(t.state))actions+=`<button class="button light" data-publish="${t.id}">ટીવી પર પ્રકાશિત કરો</button>`;return `${panel('કાર્યની વિગત',`<div class="toolbar"><span class="tag ${t.state}">${label[t.state]}</span><span class="muted">${escape(t.department)} / ${escape(s?.committee)} / ${escape(s?.name)}</span></div><h2>${escape(t.title)}</h2><p><b>આયોજન તારીખ:</b> ${escape(t.planned_for||'—')} &nbsp; <b>સ્થળ:</b> ${escape(t.place||'—')}</p><p><b>જવાબદાર:</b> ${escape(t.assigned_to||'—')}</p><p class="pre">${escape(t.details||'—')}</p>${extraSummary(t)}${t.structured_data?.import?.storage_path?`<div class="actions"><button class="button light" data-import-file="${escape(t.structured_data.import.storage_path)}">⇩ મૂળ અપલોડ કરેલી ફાઇલ જુઓ</button></div>`:``}${t.structured_data?.planning_lines?`<div class="line"></div><h3>આયોજનની એન્ટ્રીઓ</h3><p class="pre">${escape(t.structured_data.planning_lines)}</p>`:''}<div class="actions"><button class="button light" data-page="tasks">← પાછા</button>${actions}</div>`)}${panel('મૂળ સેવાની સૂચિત પ્રક્રિયા',hint(s||{name:'',form_hint:'',workflow_hint:''}))}`}
function displaysView(){return `${isAdmin()?panel('નવું ટીવી ઉમેરો',`<form id="create-display" class="form-grid"><div class="field"><label>ટીવીનું નામ *</label><input name="name" placeholder="Common Hall TV" required></div><div class="field"><label>સ્થાન</label><input name="location" placeholder="પ્રથમ માળ"></div><div class="field"><label>વિભાગ</label><select name="department">${opt('','બધા વિભાગ')}${['EDU','HRM','ADM'].map(x=>opt(x,x)).join('')}</select></div><div class="field" style="justify-content:end"><button class="button">ટીવી બનાવો</button></div></form>`):''}${panel('અલગ-અલગ ટીવી ડિસ્પ્લે',state.displays.map(d=>`<div style="padding:13px 0;border-bottom:1px solid #e9edf5"><b>${escape(d.name)}</b> <span class="pill">${escape(d.department||'Common')}</span><div class="muted small">${escape(d.location)} • ${state.publications.filter(p=>p.display_id===d.id).length} પ્રકાશન</div><div class="actions"><a class="button light" target="_blank" rel="noopener noreferrer" href="tv.html?key=${encodeURIComponent(d.access_key)}">ટીવી ડિસ્પ્લે ખોલો ↗</a><button class="button light" data-copytv="${escape(d.access_key)}">ટીવીની લિંક કૉપી કરો</button></div></div>`).join('')||notice('હજુ ટીવી બનાવ્યા નથી.'))}<div id="publish-panel"></div>`}
function usersView(){if(!isAdmin())return notice('આ વિભાગ Super Admin માટે છે.');return panel('યુઝર એકાઉન્ટ અને અધિકાર',`<form id="create-account" class="panel"><h3>નવો યુઝર બનાવો (ઈમેલ વગર)</h3><div class="field"><label>યુઝરનેમ (English letters / numbers / _)</label><input name="username" required pattern="[a-zA-Z][a-zA-Z0-9_]{2,31}" placeholder="ketul_maharaj"></div><div class="field"><label>પૂર્ણ નામ</label><input name="full_name" required></div><div class="field"><label>શરૂઆતનો પાસવર્ડ (ઓછામાં ઓછા 3 અક્ષર)</label><input name="password" required minlength="3" type="password"></div><div class="field"><label>અધિકાર</label><select name="role" class="control"><option value="samiti_sanchalak">સમિતિ સંચાલક</option><option value="department_saint">Department Saint</option><option value="super_admin">Super Admin</option></select></div><div class="field"><label>વિભાગ</label><select name="department" class="control">${['','EDU','HRM','ADM'].map(d=>`<option value="${d}">${d||'બધા વિભાગો (Super Admin)'}</option>`).join('')}</select></div><div class="field"><label>સમિતિ (સમિતિ સંચાલક માટે)</label><select name="committee_id" class="control"><option value="">—</option>${state.committees.map(c=>`<option value="${escape(c.id)}">${escape(c.department)} / ${escape(c.name)}</option>`).join('')}</select></div><button class="button">યુઝર બનાવો</button></form><div class="tablewrap"><table><thead><tr><th>નામ / યુઝરનેમ</th><th>અધિકાર</th><th>વિભાગ</th><th>સમિતિ</th><th>કાર્ય</th></tr></thead><tbody>${state.users.map(u=>`<tr data-userrow="${u.id}"><td>${escape(u.full_name)}<div class="small muted">@${escape(u.username||'હજુ username સેટ નથી')}</div></td><td><select class="control" data-role>${['pending','super_admin','department_saint','samiti_sanchalak'].map(r=>`<option ${u.role===r?'selected':''} value="${r}">${r}</option>`).join('')}</select></td><td><select class="control" data-dept>${['','EDU','HRM','ADM'].map(d=>`<option ${u.department===(d||null)?'selected':''} value="${d}">${d||'—'}</option>`).join('')}</select></td><td><select class="control" data-committee><option value="">—</option>${state.committees.map(c=>`<option ${u.committee_id===c.id?'selected':''} value="${escape(c.id)}">${escape(c.department)} / ${escape(c.name)}</option>`).join('')}</select></td><td><button class="button" data-saveuser="${u.id}">સાચવો</button> <button class="button light" data-resetuser="${u.id}">પાસવર્ડ રીસેટ</button> ${!u.username?`<button class="button light" data-migrateuser="${u.id}">જૂનો યુઝર બદલો</button>`:""}</td></tr>`).join('')}</tbody></table></div>`)}
function wire(){wireImport();document.querySelectorAll('[data-import-file]').forEach(b=>b.onclick=async()=>{try{const {data,error}=await db.storage.from('stk-imports').createSignedUrl(b.dataset.importFile,120);if(error)throw error;window.open(data.signedUrl,'_blank','noopener')}catch(e){say(e.message,true)}});document.querySelectorAll('[data-edu-new]').forEach(b=>b.onclick=()=>{state.serviceFilter=b.dataset.eduNew;go('new')});document.querySelectorAll('[data-page]').forEach(b=>{b.onclick=()=>go(b.dataset.page)});document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{state.editId=b.dataset.open;state.page='detail';render()});document.querySelectorAll('[data-newservice]').forEach(b=>b.onclick=()=>{state.serviceFilter=b.dataset.newservice;go('new')});const exportBtn=$('#export-csv');if(exportBtn)exportBtn.onclick=exportCsv;const calPrev=$('#cal-prev'),calNext=$('#cal-next');if(calPrev)calPrev.onclick=()=>{calendarOffset--;view()};if(calNext)calNext.onclick=()=>{calendarOffset++;view()};document.querySelectorAll('[data-report-state]').forEach(b=>b.onclick=()=>{state.page='tasks';render();const st=$('#t-state');if(st){st.value=b.dataset.reportState;st.dispatchEvent(new Event('change'))}});const ss=$('#s-search');if(ss)ss.oninput=()=>{const avail=state.services.filter(s=>isAdmin()||s.department===state.profile.department);const g=avail.reduce((a,s)=>(a[s.committee_id]??=[]).push(s),{});$('#service-groups').innerHTML=serviceGroups(g,ss.value.toLowerCase());wire()};const ts=$('#t-search'),st=$('#t-state');if(ts&&st){const filter=()=>{$('#filtered-tasks').innerHTML=taskTable(state.tasks.filter(t=>(!st.value||t.state===st.value)&&(`${t.title} ${t.assigned_to} ${t.service_id}`).toLowerCase().includes(ts.value.toLowerCase())));document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{state.editId=b.dataset.open;state.page='detail';render()})};ts.oninput=filter;st.onchange=filter}const sel=$('#service-select');if(sel){if(state.serviceFilter)sel.value=state.serviceFilter;$('#service-help').innerHTML=hint(serviceById(sel.value));sel.onchange=()=>{$('#service-help').innerHTML=hint(serviceById(sel.value));$('#dynamic-fields').innerHTML=serviceFields(serviceById(sel.value));wirePlannerRows()}}wirePlannerRows();const nw=$('#new-work');if(nw)nw.onsubmit=async e=>{e.preventDefault();const f=new FormData(nw),s=serviceById(f.get('service_id'));try{await req(db.from('work_items').insert({service_id:s.id,department:s.department,committee_id:s.committee_id,title:f.get('title'),details:f.get('details'),planned_for:f.get('planned_for')||null,place:f.get('place'),assigned_to:f.get('assigned_to'),structured_data:{planning_lines:f.get('planning_lines'),form_type:formKind(s),extra:Object.fromEntries([...f.entries()].filter(([k])=>k.startsWith('extra_'))),events:readPlannerRows()},created_by:state.user.id}).select().single());say('કાર્યનું ડ્રાફ્ટ સાચવાયું');state.serviceFilter='';await reload();go('tasks')}catch(ex){say(ex.message,true)}};document.querySelectorAll('[data-transition]').forEach(b=>b.onclick=async()=>{const t=state.tasks.find(x=>x.id===state.editId);if(!confirm(`સ્થિતિ બદલીને “${label[b.dataset.transition]}” કરવી છે?`))return;try{await req(db.from('work_items').update({state:b.dataset.transition}).eq('id',t.id));await req(db.from('activity_log').insert({work_item_id:t.id,actor:state.user.id,event:b.dataset.transition}));await reload();render();say('સ્થિતિ બદલાઈ')}catch(ex){say(ex.message,true)}});document.querySelectorAll('[data-publish]').forEach(b=>b.onclick=()=>publishForm(b.dataset.publish));const cd=$('#create-display');if(cd)cd.onsubmit=async e=>{e.preventDefault();const f=new FormData(cd);try{await req(db.from('displays').insert({name:f.get('name'),location:f.get('location'),department:f.get('department')||null}));await reload();render();say('નવું ટીવી ઉમેરાયું')}catch(ex){say(ex.message,true)}};document.querySelectorAll('[data-copytv]').forEach(b=>b.onclick=()=>{const link=new URL('tv.html?key='+encodeURIComponent(b.dataset.copytv),location.href).href;navigator.clipboard.writeText(link).then(()=>say('ટીવી લિંક કૉપી થઈ')).catch(()=>prompt('ટીવીની લિંક',link))});document.querySelectorAll('[data-unpublish]').forEach(b=>b.onclick=async()=>{if(!confirm('આ માહિતી TV પરથી દૂર કરવી છે?'))return;try{await req(db.from('publications').delete().eq('id',b.dataset.unpublish));await reload();render();say('પ્રકાશન દૂર થયું')}catch(e){say(e.message,true)}});const ca=$('#create-account');if(ca)ca.onsubmit=async e=>{e.preventDefault();const f=new FormData(ca);const args=Object.fromEntries(f.entries());args.action='create_user';args.username=String(args.username).trim().toLowerCase();if(!goodUsername(args.username))return say('યુઝરનેમ યોગ્ય નથી',true);try{const r=await accountApi(args,true);alert('યુઝર બનાવ્યો: '+args.username+'\nRecovery Code (માત્ર એક વખત દેખાશે): '+r.recovery_code+'\nઆ કોડ સંબંધિત સંતને સુરક્ષિત રીતે આપશો.');ca.reset();await reload();render()}catch(ex){say(ex.message,true)}};document.querySelectorAll('[data-migrateuser]').forEach(b=>b.onclick=async()=>{const u=state.users.find(x=>x.id===b.dataset.migrateuser);const username=prompt('જૂના યુઝર માટે નવું Username:');if(username===null)return;const clean=username.trim().toLowerCase();if(!goodUsername(clean))return say('યુઝરનેમ અમાન્ય છે',true);if(!confirm('જૂના એકાઉન્ટનો પાસવર્ડ યથાવત્ રાખીને Username @'+clean+' કરવો છે?'))return;try{const r=await accountApi({action:'migrate_user',old_email:u.email,username:clean},true);alert('જૂનો યુઝર બદલાયો. Recovery Code: '+r.recovery_code);await reload();render()}catch(ex){say(ex.message,true)}});document.querySelectorAll('[data-resetuser]').forEach(b=>b.onclick=async()=>{const u=state.users.find(x=>x.id===b.dataset.resetuser);const password=prompt('નવો પાસવર્ડ દાખલ કરો (ઓછામાં ઓછા 3 અક્ષર):');if(password===null)return;if(password.length<3)return say('ઓછામાં ઓછા 3 અક્ષર જરૂરી',true);try{const r=await accountApi({action:'reset_password',user_id:u.id,password},true);alert('@'+u.username+' નો પાસવર્ડ બદલાયો. નવો Recovery Code: '+r.recovery_code+'\nઆ કોડ સુરક્ષિત રીતે આપશો.')}catch(ex){say(ex.message,true)}});document.querySelectorAll('[data-saveuser]').forEach(b=>b.onclick=async()=>{const tr=b.closest('[data-userrow]'),role=tr.querySelector('[data-role]').value,department=tr.querySelector('[data-dept]').value||null,committee_id=tr.querySelector('[data-committee]').value||null;if(role==='samiti_sanchalak'&&!committee_id)return say('સમિતિ પસંદ કરો',true);if(committee_id&&state.committees.find(c=>c.id===committee_id)?.department!==department)return say('સમિતિ અને વિભાગ મેળ ખાતાં નથી',true);try{await req(db.from('profiles').update({role,department,committee_id:role==='samiti_sanchalak'?committee_id:null}).eq('id',b.dataset.saveuser));say('યુઝર અધિકાર સાચવાયા');await reload();render()}catch(ex){say(ex.message,true)}})}
function publishForm(id){const t=state.tasks.find(x=>x.id===id);const displays=state.displays.filter(d=>isAdmin()||!d.department||d.department===t.department);if(!displays.length)return say('સૌપ્રથમ Super Admin ટીવી બનાવે',true);$('#content').insertAdjacentHTML('beforeend',panel('આ કાર્ય ટીવી પર પ્રકાશિત કરો',`<form id="publish-form"><div class="form-grid"><div class="field span2"><label>કયા ટીવી પર? *</label><select name="display_id">${displays.map(x=>opt(x.id,x.name+' • '+(x.department||'Common'))).join('')}</select></div><div class="field span2"><label>જાહેર શીર્ષક *</label><input required name="headline" value="${escape(t.title)}"></div><div class="field span2"><label>ટીવી પર દેખાડવા માટેની માત્ર જાહેર માહિતી *</label><textarea required name="public_text">${escape(t.structured_data?.planning_lines||t.details||'')}</textarea></div><div class="field"><label>શરૂ થવાનો સમય (વૈકલ્પિક)</label><input name="start_at" type="datetime-local"></div><div class="field"><label>પૂરો થવાનો સમય (વૈકલ્પિક)</label><input name="end_at" type="datetime-local"></div><div class="field"><label>પ્રાથમિકતા (0–10)</label><input name="priority" type="number" value="0" min="0" max="10"></div></div>${notice('અહીં ફક્ત જાહેર કરી શકાય તેવી માહિતી દાખલ કરો. વ્યક્તિગત, ગોપનીય કે આંતરિક નોંધ અહીં મૂકશો નહીં.')}<div class="actions"><button class="button">આ ટીવી પર પ્રકાશિત કરો</button></div></form>`));$('#publish-form').scrollIntoView({behavior:'smooth'});$('#publish-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);const d=Object.fromEntries(f);d.item_id=id;d.published_by=state.user.id;d.priority=Number(d.priority)||0;d.start_at=d.start_at?new Date(d.start_at).toISOString():null;d.end_at=d.end_at?new Date(d.end_at).toISOString():null;try{await req(db.from('publications').upsert(d,{onConflict:'display_id,item_id'}));say('માહિતી ટીવી પર પ્રકાશિત થઈ');await reload();render()}catch(ex){say(ex.message,true)}}}

let calendarOffset=0;
const formDefinitions={planning:[['extra_month','આયોજનનો મહિનો','month'],['extra_objective','મુખ્ય ઉદ્દેશ','text'],['extra_audience','લક્ષિત સંતો / મુક્તો','text']],meeting:[['extra_agenda','બેઠકનો એજન્ડા','textarea'],['extra_decisions','નિર્ણયો અને અનુસરણ','textarea'],['extra_attendees','હાજર રહેવાના સભ્યો','text']],attendance:[['extra_count','સંખ્યાત્મક હાજરી','number'],['extra_absent','ગેરહાજર સભ્યો','textarea'],['extra_followup','અનુસરણ નોંધ','textarea']],training:[['extra_topic','વિષય / તાલીમ મોડ્યુલ','text'],['extra_trainer','ટ્રેનર / માર્ગદર્શક','text'],['extra_participants','ભાગ લેનારની સંખ્યા','number'],['extra_feedback','પ્રતિભાવ અને પરિણામ','textarea']],inventory:[['extra_item','સામગ્રી / વસ્તુનું નામ','text'],['extra_quantity','જથ્થો','number'],['extra_unit','એકમ','text'],['extra_source','માગણી / સ્રોત','text']],maintenance:[['extra_issue','સમસ્યાની વિગત','textarea'],['extra_urgency','પ્રાથમિકતા (સામાન્ય/તાત્કાલિક)','text'],['extra_resolution','સમાધાન અને ચકાસણી','textarea']],seva:[['extra_duty','સેવા / ફરજનું નામ','text'],['extra_people','સેવા માટેના સંતો / મુક્તો','textarea'],['extra_shift','સમય / પાળી','text'],['extra_result','સેવા પૂર્ણતાની નોંધ','textarea']],library:[['extra_book','પુસ્તક / સામગ્રી','text'],['extra_issue_date','ઇશ્યૂ તારીખ','date'],['extra_return_date','પરત તારીખ','date'],['extra_borrower','લેનાર','text']],general:[['extra_expected','અપેક્ષિત પરિણામ','textarea'],['extra_resources','જરૂરી સાધનો / મદદ','textarea'],['extra_followup','પછીની કામગીરી','textarea']]};
function formKind(s){const a=((s?.name||'')+' '+(s?.committee||'')+' '+(s?.form_hint||'')).toLowerCase();if(/planning|આયોજન|schedule|પ્લાન/.test(a))return 'planning';if(/meeting|બેઠક|સભા/.test(a))return 'meeting';if(/attendance|હાજરી/.test(a))return 'attendance';if(/library|પુસ્તક/.test(a))return 'library';if(/stock|store|સ્ટોર|જથ્થો|સામગ્રી|purchase/.test(a))return 'inventory';if(/maintenance|મરામત|ફરિયાદ/.test(a))return 'maintenance';if(/training|તાલીમ|study|અભ્યાસ|લર્નિંગ/.test(a))return 'training';if(/seva|સેવા|allocation|ફાળવણી|ડ્યુટી/.test(a))return 'seva';return 'general'}
function serviceFields(s){const k=formKind(s);const fields=formDefinitions[k];return `<div class="field-section"><div class="section-heading"><span>✧</span><div><b>આ સેવાનું વિશિષ્ટ ફોર્મ</b><small>${escape(s?.committee||'')} • ${escape(s?.name||'')}</small></div><span class="pill">${k}</span></div><div class="form-grid">${fields.map(([key,title,type])=>`<div class="field ${type==='textarea'?'span2':''}"><label>${title}</label>${type==='textarea'?`<textarea name="${key}" rows="3"></textarea>`:`<input name="${key}" type="${type}" ${type==='number'?'min="0"':''}>`}</div>`).join('')}</div>${k==='planning'?`<div class="section-heading"><span>▦</span><div><b>આયોજનની તારીખવાર એન્ટ્રી</b><small>દરેક પ્રવૃત્તિ અલગ પંક્તિમાં ઉમેરો</small></div></div><div id="planner-rows"></div><button type="button" class="button light" id="add-plan-row">＋ નવી પ્રવૃત્તિ ઉમેરો</button>`:''}</div>`}
function wirePlannerRows(){const el=$('#planner-rows'),btn=$('#add-plan-row');if(!el||!btn)return;function add(){el.insertAdjacentHTML('beforeend',`<div class="planner-row"><input aria-label="તારીખ" type="date" data-pdate><input aria-label="સમય" type="time" data-ptime><input aria-label="પ્રવૃત્તિ" placeholder="પ્રવૃત્તિનું નામ" data-pname><input aria-label="સ્થળ" placeholder="સ્થળ" data-pplace><button type="button" class="button light" data-del-row>×</button></div>`);const row=el.lastElementChild;row.querySelector('[data-del-row]').onclick=()=>row.remove()}btn.onclick=add;if(!el.children.length)add()}
function readPlannerRows(){return [...document.querySelectorAll('.planner-row')].map(row=>({date:row.querySelector('[data-pdate]').value,time:row.querySelector('[data-ptime]').value,title:row.querySelector('[data-pname]').value,place:row.querySelector('[data-pplace]').value})).filter(x=>x.title||x.date)}
function extraSummary(t){const extra=t.structured_data?.extra||{},ev=t.structured_data?.events||[];let html=Object.entries(extra).filter(([k,v])=>String(v||'').trim()).map(([k,v])=>{const x=Object.values(formDefinitions).flat().find(a=>a[0]===k);return `<div class="extra-line"><span>${escape(x?.[1]||k)}</span><b>${escape(v)}</b></div>`}).join('');if(ev.length)html+=`<div class="tablewrap"><table><thead><tr><th>તારીખ</th><th>સમય</th><th>પ્રવૃત્તિ</th><th>સ્થળ</th></tr></thead><tbody>${ev.map(e=>`<tr><td>${escape(e.date)}</td><td>${escape(e.time)}</td><td>${escape(e.title)}</td><td>${escape(e.place)}</td></tr>`).join('')}</tbody></table></div>`;return html?`<div class="extra-summary"><h3>સેવાની વિગતવાર માહિતી</h3>${html}</div>`:''}
function calendarView(){const now=new Date();const target=new Date(now.getFullYear(),now.getMonth()+calendarOffset,1);const y=target.getFullYear(),m=target.getMonth();const first=(new Date(y,m,1).getDay()+6)%7;const days=new Date(y,m+1,0).getDate();const records=state.tasks.filter(t=>t.planned_for&&t.planned_for.slice(0,7)===`${y}-${String(m+1).padStart(2,'0')}`);const week=['સોમ','મંગળ','બુધ','ગુરુ','શુક્ર','શનિ','રવિ'];let cells=[...Array(first)].map(()=>'<div class="cal-day blank"></div>');for(let day=1;day<=days;day++){let key=`${y}-${String(m+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`;let hits=records.filter(t=>t.planned_for===key);cells.push(`<div class="cal-day"><span class="cal-date">${day}</span>${hits.slice(0,4).map(t=>`<button class="cal-event" data-open="${t.id}" title="${escape(t.title)}">${escape(t.title)}</button>`).join('')}${hits.length>4?`<small>+${hits.length-4} વધુ</small>`:''}</div>`)}return `<div class="calendar-toolbar"><div><h2>${target.toLocaleDateString('gu-IN',{month:'long',year:'numeric'})}</h2><p class="muted small">મંજૂર તથા ડ્રાફ્ટ સહિત આપને અધિકૃત આયોજન</p></div><div class="actions"><button class="button light" id="cal-prev">← અગાઉનો</button><button class="button light" id="cal-next">પછીનો →</button></div></div><div class="calendar-grid">${week.map(w=>`<b class="cal-header">${w}</b>`).join('')}${cells.join('')}</div>${panel('આ મહિનાની પ્રવૃત્તિઓ',taskTable(records))}`}
function approvalsView(){const all=state.tasks.filter(t=>t.state==='submitted');const pending=all.filter(canManage);return `<div class="welcome mini"><div><span class="eyebrow">APPROVAL WORKFLOW</span><h2>મંજૂરી ઇનબૉક્સ</h2><p>વિભાગીય સંત અથવા Super Admin મંજૂરી આપી શકે છે.</p></div><span class="approval-number">${pending.length}</span></div>${leader()?panel('મંજૂરી માટે આવેલી કામગીરી',taskTable(pending)):notice('આ કામગીરી જોવા અને મંજૂર કરવાની સત્તા Department Saint / Super Admin પાસે છે.')}${panel('મંજૂરીની પ્રક્રિયા',`<div class="lead">ડ્રાફ્ટ → મંજૂરી માટે મોકલો → મંજૂર / સુધારા માટે પરત → અમલ → ચકાસણી → પસંદ કરેલા ટીવી પર પ્રકાશન.</div>`)}`}
function reportsView(){const t=state.tasks;const states=Object.entries(label).map(([key,value])=>({key,value,count:t.filter(x=>x.state===key).length}));const departments=['EDU','HRM','ADM'].map(d=>({name:d,items:t.filter(x=>x.department===d)}));const max=Math.max(1,...states.map(x=>x.count));return `<div class="welcome mini"><div><span class="eyebrow">REPORTING & EXPORT</span><h2>કાર્યાલયનો રિપોર્ટ</h2><p>તમારી સત્તા મુજબ ઉપલબ્ધ માહિતીનો રિપોર્ટ અને CSV નિકાસ.</p></div><button class="button" id="export-csv">↓ CSV ડાઉનલોડ</button></div><div class="two-col">${panel('સ્થિતિ પ્રમાણે કામગીરી',states.map(x=>`<button class="chart-row" data-report-state="${x.key}"><span>${x.value}</span><span class="bar-track"><span class="bar-fill" style="width:${Math.max(x.count?5:0,100*x.count/max)}%"></span></span><b>${x.count}</b></button>`).join(''))}${panel('વિભાગ પ્રમાણે કામગીરી',departments.filter(x=>isAdmin()||state.profile.department===x.name).map(x=>`<div class="dept-report"><b>${x.name}</b><span>${x.items.length} નોંધો</span><small>${x.items.filter(y=>y.state==='verified').length} ચકાસાયેલાં</small></div>`).join(''))}</div>${panel('ડેટાની યાદી',taskTable(t.slice(0,75)))}`}
function exportCsv(){const headers=['ID','વિભાગ','સમિતિ','સેવા','શીર્ષક','તારીખ','જવાબદાર','સ્થિતિ','સ્થળ','વિગતો'];const rows=state.tasks.map(t=>[t.id,t.department,t.committee_id,serviceById(t.service_id)?.name,t.title,t.planned_for,t.assigned_to,label[t.state],t.place,t.details]);const csv='\uFEFF'+[headers,...rows].map(row=>row.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\r\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='STK_Report_'+new Date().toISOString().slice(0,10)+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function publicationCards(){if(!state.publications.length)return '';const filtered=state.publications.filter(p=>{const t=state.tasks.find(t=>t.id===p.item_id);return t&&canManage(t)});return panel('પ્રકાશિત સૂચનાઓનું સંચાલન',filtered.map(p=>`<div class="pub-row"><div><b>${escape(p.headline)}</b><div class="small muted">${escape(state.displays.find(d=>d.id===p.display_id)?.name||'TV')} • ${escape(p.public_text.slice(0,95))}</div></div><button class="button light" data-unpublish="${p.id}">ડિસ્પ્લેથી દૂર કરો</button></div>`).join('')||notice('આપને સંચાલિત કરી શકાય એવી પ્રકાશિત સૂચના નથી.'))}


// V5 IMPORT: spreadsheets -> preview -> explicit approval -> work_items; original files -> private Storage.
let importState={file:null,rows:[],headers:[],preview:[],kind:'',serviceId:'',mapping:{},busy:false};
function importView(){const available=state.services.filter(canWrite);return `<section class="panel"><h2>⇧ જૂના ઓફલાઇન ડેટા ઇમ્પોર્ટ કરો</h2><p class="muted">Excel (.xlsx/.xls), CSV, JSON ફાઇલોની પંક્તિઓ ઓનલાઇન કાર્યરેકોર્ડમાં રૂપાંતરિત કરો. PDF/Word/અન્ય ફાઇલને સુરક્ષિત રેકોર્ડ સાથે જોડીને સાચવી શકાય છે.</p><div class="import-flow"><b>① ફાઇલ પસંદ કરો</b><span>→</span><b>② કોલમ ચકાસો</b><span>→</span><b>③ પ્રિવ્યૂ</b><span>→</span><b>④ સુરક્ષિત રીતે ઇમ્પોર્ટ</b></div><div class="form-grid"><div class="field span2"><label>સંબંધિત સેવા / સમિતિ *</label><select id="import-service" class="control">${available.map(x=>opt(x.id,`${x.department} / ${x.committee} / ${x.name}`)).join('')}</select></div><div class="field span2"><label>જૂની ફાઇલ પસંદ કરો (20 MB સુધી)</label><input id="import-file" type="file" accept=".xlsx,.xls,.csv,.json,.pdf,.doc,.docx,.txt,.png,.jpg,.jpeg" /></div></div><div id="import-status" role="status" aria-live="polite"></div><div id="import-preview"></div></section>${panel('આયાતની સલામતી',notice('મૂળ ફાઇલ Private Storageમાં રહેશે. આયાત થયેલા રેકોર્ડ Draft તરીકે બનશે; ટીવી પર સ્વચાલિત પ્રકાશિત નહીં થાય. આ માટે Supabaseમાં V5 Storage SQL એક વખત ચલાવવો જરૂરી છે.'))}`}
const IMPORT_FIELDS=[['title','શીર્ષક / Activity'],['planned_for','તારીખ / Date'],['assigned_to','જવાબદાર / Owner'],['place','સ્થળ / Place'],['details','વિગત / Description']];
const HEADER_ALIASES={title:['title','activity','task','work','વિષય','પ્રવૃત્તિ','શીર્ષક','કાર્ય'],planned_for:['date','planned_for','તારીખ','day','schedule'],assigned_to:['owner','assigned_to','responsible','person','member','જવાબદાર','સંત','સેવક'],place:['place','venue','location','સ્થળ'],details:['details','notes','description','remarks','વિગત','નોંધ']};
const cleanName=s=>String(s??'').trim().toLowerCase().replace(/[\s_\-]+/g,'');
function guessedHeader(field,headers){const aliases=HEADER_ALIASES[field].map(cleanName);return headers.find(h=>aliases.includes(cleanName(h)))||headers.find(h=>aliases.some(a=>cleanName(h).includes(a)))||''}
async function parseImportFile(file){let rows=[];const extension=file.name.split('.').pop().toLowerCase();if(['xlsx','xls','csv'].includes(extension)){
 if(!window.XLSX)await new Promise((resolve,reject)=>{const js=document.createElement('script');js.src='https://cdn.jsdelivr.net/npm/xlsx@0.18.5/dist/xlsx.full.min.js';js.onload=resolve;js.onerror=()=>reject(Error('Excel Reader લોડ થયું નથી. ઇન્ટરનેટ તપાસો.'));document.head.appendChild(js)});
 const wb=window.XLSX.read(await file.arrayBuffer(),{type:'array',cellDates:true});const sheet=wb.Sheets[wb.SheetNames[0]];rows=window.XLSX.utils.sheet_to_json(sheet,{defval:'',raw:false});
 }else if(extension==='json'){const data=JSON.parse(await file.text());rows=Array.isArray(data)?data:Array.isArray(data.rows)?data.rows:Array.isArray(data.items)?data.items:[];if(!rows.length)throw Error('JSONમાં rows/items Array નથી.')}else return {rows:[],kind:'attachment'};
 if(rows.length>2000)throw Error('એક વખત 2,000થી વધુ પંક્તિઓ ઇમ્પોર્ટ ન કરો. ફાઇલ વિભાજિત કરો.');
 return {rows:rows.filter(r=>r&&typeof r==='object'&&!Array.isArray(r)),kind:'structured'};
}
function isoDate(v){if(v instanceof Date&&!isNaN(v))return v.toISOString().slice(0,10);const s=String(v??'').trim();if(!s)return null;let m=s.match(/^(\d{4})[-/](\d{1,2})[-/](\d{1,2})/);if(m)return `${m[1]}-${m[2].padStart(2,'0')}-${m[3].padStart(2,'0')}`;m=s.match(/^(\d{1,2})[\-/](\d{1,2})[\-/](\d{4})/);if(m)return `${m[3]}-${m[2].padStart(2,'0')}-${m[1].padStart(2,'0')}`;return null}
function importMappingPanel(){const rows=importState.rows;const h=importState.headers;const mapping=Object.fromEntries(IMPORT_FIELDS.map(([f])=>[f,guessedHeader(f,h)]));importState.mapping=mapping;
 return `<h3>કૉલમ મેપિંગ – ${rows.length} નોંધો</h3><p class="muted small">મૂળ Excelની કોઈપણ કૉલમને પોર્ટલના યોગ્ય ફીલ્ડ સાથે જોડો. બધી નોંધો પહેલાં Previewમાં જોઈ શકાય છે.</p><div class="form-grid">${IMPORT_FIELDS.map(([f,name])=>`<div class="field"><label>${name}</label><select class="control" data-map="${f}">${opt('','કૉલમ પસંદ કરો')}${h.map(x=>`<option value="${escape(x)}" ${mapping[f]===x?'selected':''}>${escape(x)}</option>`).join('')}</select></div>`).join('')}</div><div class="actions"><button id="import-refresh" class="button light">પ્રિવ્યૂ અપડેટ કરો</button><button id="import-save" class="button">ચકાસીને ઇમ્પોર્ટ કરો</button></div><div id="import-table"></div>`}
function previewImport(){importState.mapping=Object.fromEntries([...document.querySelectorAll('[data-map]')].map(x=>[x.dataset.map,x.value]));const m=importState.mapping;if(!m.title){$('#import-table').innerHTML=notice('કૃપા કરીને શીર્ષક / Activity કૉલમ પસંદ કરો.',true);return}const sample=importState.rows.slice(0,12).map(r=>({title:String(r[m.title]??''),date:isoDate(r[m.planned_for]),owner:String(r[m.assigned_to]??''),place:String(r[m.place]??'')}));$('#import-table').innerHTML=`<h3>ઇમ્પોર્ટ પ્રિવ્યૂ (પ્રથમ 12)</h3><div class="tablewrap"><table><thead><tr><th>કાર્ય</th><th>તારીખ</th><th>જવાબદાર</th><th>સ્થળ</th></tr></thead><tbody>${sample.map(r=>`<tr><td>${escape(r.title)}</td><td>${escape(r.date||'—')}</td><td>${escape(r.owner)}</td><td>${escape(r.place)}</td></tr>`).join('')}</tbody></table></div>`}
async function saveOriginalFile(file,service){const ext=file.name.split('.').pop().replace(/[^a-zA-Z0-9]/g,'').toLowerCase();const random=crypto.randomUUID();const key=`${state.user.id}/${service.department}/${service.committee_id}/${random}.${ext}`;const {error}=await db.storage.from('stk-imports').upload(key,file,{upsert:false,contentType:file.type||'application/octet-stream'});if(error)throw Error('Original file upload: '+error.message);return key}
async function runImport(){if(importState.busy)return;const file=importState.file,service=serviceById($('#import-service').value);if(!file||!service||!canWrite(service))return say('યોગ્ય ફાઇલ અને સેવા પસંદ કરો.',true);const structured=importState.kind==='structured',map=importState.mapping;
 if(structured&&!map.title)return say('શીર્ષકની કોલમ પસંદ કરો.',true);
 if(!confirm(structured?`${importState.rows.length} નોંધો ${service.department} / ${service.committee} માં Draft તરીકે ઉમેરવી છે?`:'આ ફાઇલ સુરક્ષિત Storageમાં સાચવીને એક Draft રેકોર્ડ બનાવવો છે?'))return;
 importState.busy=true;const btn=$('#import-save');if(btn)btn.disabled=true;let uploadedKey=null,inserted=0;
 try{uploadedKey=await saveOriginalFile(file,service);const chunkSize=40;let records=[];
 if(structured){const raw=importState.rows;records=raw.map((r,i)=>({service_id:service.id,department:service.department,committee_id:service.committee_id,title:String(r[map.title]??'').trim().slice(0,250),planned_for:isoDate(map.planned_for?r[map.planned_for]:null),assigned_to:String(r[map.assigned_to]??'').slice(0,250),place:String(r[map.place]??'').slice(0,250),details:String(r[map.details]??'').slice(0,4000),created_by:state.user.id,state:'draft',structured_data:{import:{filename:file.name,storage_path:uploadedKey,row:i+2,imported_at:new Date().toISOString()},source_row:r}})).filter(r=>r.title)}else{records=[{service_id:service.id,department:service.department,committee_id:service.committee_id,title:file.name.slice(0,250),details:'જૂની ઓફલાઇન ફાઇલ અપલોડ કરેલી છે.',created_by:state.user.id,state:'draft',structured_data:{import:{filename:file.name,storage_path:uploadedKey,imported_at:new Date().toISOString()},attachment:true}}]}
 if(!records.length)throw Error('કોઈ માન્ય શીર્ષક ધરાવતી નોંધ નથી.');for(let i=0;i<records.length;i+=chunkSize){await req(db.from('work_items').insert(records.slice(i,i+chunkSize)));inserted+=Math.min(chunkSize,records.length-i);$('#import-status').innerHTML=notice(`${inserted} / ${records.length} નોંધો સેવ થઈ ગઈ છે…`)}
 say(`${inserted} નોંધો સફળતાપૂર્વક આયાત થઈ`);await reload();go('tasks');
 }catch(e){$('#import-status').innerHTML=notice(`ઇમ્પોર્ટ અટક્યું: ${escape(e.message)}. ${inserted} નોંધો પહેલેથી સેવ થઈ હોઈ શકે; ફરી ઇમ્પોર્ટ કરતાં પહેલાં તપાસો.`,true)}finally{importState.busy=false;if(btn)btn.disabled=false}}
function wireImport(){const fileInput=$('#import-file');if(!fileInput)return;fileInput.onchange=async()=>{const file=fileInput.files?.[0];if(!file)return;if(file.size>20*1024*1024){say('20 MB કરતાં નાની ફાઇલ પસંદ કરો.',true);fileInput.value='';return}importState.file=file;$('#import-status').innerHTML=notice('ફાઇલ ચકાસાઈ રહી છે…');try{const parsed=await parseImportFile(file);importState.kind=parsed.kind;importState.rows=parsed.rows;importState.headers=[...new Set(parsed.rows.flatMap(row=>Object.keys(row)))].slice(0,120);$('#import-status').innerHTML=notice(`${escape(file.name)} • ${parsed.kind==='structured'?parsed.rows.length+' પંક્તિઓ':'દસ્તાવેજ તરીકે સાચવાશે'}`);$('#import-preview').innerHTML=parsed.kind==='structured'?importMappingPanel():'<p>દસ્તાવેજ Private Storageમાં અપલોડ થશે અને સમિતિના Draft રેકોર્ડ સાથે જોડાશે.</p><button class="button" id="import-save">ફાઇલ સુરક્ષિત રીતે સાચવો</button>';$('#import-refresh')?.addEventListener('click',previewImport);$('#import-save')?.addEventListener('click',runImport);if(parsed.kind==='structured')previewImport()}catch(e){$('#import-status').innerHTML=notice(escape(e.message),true)}}}

setup();
